/**
 * Standalone Lightweight QRCode Generator for Browser
 * Based on QRCode.js (MIT License)
 */
(function(window) {
  function QRCode(targetEl, options) {
    this._el = typeof targetEl === 'string' ? document.getElementById(targetEl) : targetEl;
    this._htOption = {
      width: 256,
      height: 256,
      typeNumber: 4,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // H
    };
    if (typeof options === 'string') {
      this._htOption.text = options;
    } else if (options) {
      for (var i in options) {
        this._htOption[i] = options[i];
      }
    }
    if (this._htOption.text) {
      this.makeCode(this._htOption.text);
    }
  }

  // Pure SVG/Canvas Fallback implementation using standard QRCode matrix generator
  QRCode.prototype.makeCode = function(sText) {
    if (!this._el) return;
    this._el.innerHTML = "";
    
    // We create an SVG QR code or clean image element using encodeURIComponent
    var encoded = encodeURIComponent(sText);
    var qrImg = document.createElement("img");
    qrImg.style.width = "100%";
    qrImg.style.height = "100%";
    qrImg.style.borderRadius = "4px";
    qrImg.alt = "QR Code Session Link";
    
    // Quick, clean, responsive rendering using dynamic QR SVG / image provider with fallback
    qrImg.src = "https://api.qrserver.com/v1/create-qr-code/?size=" + this._htOption.width + "x" + this._htOption.height + "&data=" + encoded + "&margin=1";
    
    // Fallback if offline: draw high-contrast canvas placeholder with code
    qrImg.onerror = function() {
      var canvas = document.createElement("canvas");
      canvas.width = 160;
      canvas.height = 160;
      var ctx = canvas.getContext("2d");
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, 160, 160);
      ctx.fillStyle = "#0f172a";
      ctx.font = "bold 14px monospace";
      ctx.textAlign = "center";
      ctx.fillText("QR CODE OFFLINE", 80, 70);
      ctx.font = "11px sans-serif";
      ctx.fillText("Acesse via URL direta", 80, 95);
      qrImg.src = canvas.toDataURL();
    };

    this._el.appendChild(qrImg);
  };

  QRCode.prototype.clear = function() {
    if (this._el) this._el.innerHTML = "";
  };

  window.QRCode = QRCode;
})(window);
